from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations, product
import heapq


def _dependency_solver(data, maximize, descending_names):
    packages = data["packages"]
    names = sorted(packages, reverse=descending_names)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows_by_version = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }

    choices = {}
    for name in names:
        versions = [v for v in rows_by_version[name]
                    if v not in blocked.get(name, [])
                    and (name not in pins or v == pins[name])]
        choices[name] = sorted(versions, reverse=maximize) + [-1]
        if not maximize:
            choices[name] = [-1] + sorted(versions)

    roots = data["roots"]
    for values in product(*(choices[name] for name in names)):
        selected = {name: version for name, version in zip(names, values)
                    if version != -1}
        if any(name not in selected or
               not bounds[0] <= selected[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in selected}
        valid = True
        for name, version in selected.items():
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target)
                if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges[name]):
                return False
            state[name] = 2
            return True

        if any(not visit(name) for name in selected):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(selected):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _build_dependency_solver(maximize, descending_names):
    return lambda data: _dependency_solver(data, maximize, descending_names)


def _component_06(data):
    def rounded(numerator, denominator):
        if data["rounding"] == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        compatible = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue

        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if coupons:
                durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
            for index, duration in enumerate(durations):
                next_coupons = coupons - (1 if index == 1 else 0)
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_coupons)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_coupons))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_dependency_solver(True, False),
    "component_02": _build_dependency_solver(False, False),
    "component_03": _build_dependency_solver(True, True),
    "component_04": _build_dependency_solver(False, True),
    "component_05": _build_dependency_solver(True, False),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
